import {LINEAGES,STATS,XP,buildPet,catalog} from './catalog.mjs';
import {verifiedPetPanel} from './verified-panel.mjs';
import {analyzeBattleReplay} from './battle-report.mjs';
import {battleReportMarkup} from './battle-report-view.mjs';
import {values} from './combat.mjs';
import {commandCenterMarkup} from './command-center.mjs';
import {styleLabMarkup,mountStyleLab} from './style-lab.mjs';
import {activePresentation,updatePresentation} from './presentation.mjs';
import {equippedInspectorMarkup,mountEquippedInspector} from './equipped-inspector.mjs';
import {ArenaRenderer,toggleSound,playSound} from './render.mjs?ui=1.9&rev=3&motion=1&command=1&equipped=1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let me=null,config=null,tab='arena',draft=null,room=null,tournament=null,renderer=null,polling=false,networkBusy=false,lastRevision=-1,lastLog=0,clockOffset=0,toastTimer,routeKey='',spectatorShare=null,firstRunPrompt=false;
let disconnected=false,submitting=false,labController=null,replaySpeed=1,poseInspector=null;
let workshopBranch='attack',workshopPanel='moves';
let replayRequest=0,replay=null,replayIndex=0,replayTimer=null,board=null,boardPollAt=0;
let presenceWanted=false,presenceLease=null,presenceEpoch=0,presenceBusy=false,presenceAttemptAt=0,lobbyPollAt=0,fightIntro=null;
const main=$('#main');
document.body.classList.add('game-ui','arcade-ui');document.body.dataset.uiRelease='1.9-arcade-ui';document.body.dataset.presentationRevision='impact-2';document.body.dataset.choreographyRevision='travel-1';document.body.classList.add('impact-ui');
// View tokens stay local; never sent in requests or exports.
let requestSerial=0;const appliedReads=new Map(),responseTiming=new WeakMap();
let viewGeneration=0,requestGeneration=0,navigating=false,resultTimer=null,resultDeadline=0,resultIdentity=null;
const stale=()=>Object.assign(new Error('Superseded view'),{stale:true});
const ticket=()=>({view:viewGeneration,request:requestGeneration,hash:location.hash});
const current=t=>t.view===viewGeneration&&t.request===requestGeneration&&t.hash===location.hash;
function beginView(){document.querySelector('#game-panel')?.close();leavePresence();clearFightIntro();renderMatchNotice({});viewGeneration++;requestGeneration++;appliedReads.clear();replayRequest++;navigating=true;networkBusy=false;submitting=false;room=null;tournament=null;replay=null;spectatorShare=null;lastRevision=-1;lastLog=0;clearResult();setContent('<section class="entry-screen" role="status" aria-busy="true">Loading selected view…</section>');}
function clearResult(){clearTimeout(resultTimer);resultTimer=null;resultDeadline=0;resultIdentity=null;}
function revealResult(){clearTimeout(resultTimer);resultTimer=null;resultDeadline=0;const panel=$('.terminal-result');if(panel){panel.hidden=false;panel.className='result-overlay';}}
function pendingControls(pending){main.querySelectorAll('button').forEach(b=>{if(pending&&!b.disabled&&(/^(move|join|ready|concede|confirm-match|direct-challenge|invite-decline|room-post|board-(post|accept|create)|save-build|rematch|practice|guided-practice|practice-guide-(skip|replay)|challenge|block-player|report-(player|category)|spectator-(consent|create|revoke)|tournament-spectator-(consent|create|revoke)|.*-tournament)$/.test(b.dataset.action||'')||b.closest('form'))){b.dataset.requestDisabled='true';b.disabled=true;}else if(!pending&&b.dataset.requestDisabled){delete b.dataset.requestDisabled;b.disabled=false;}});}
function connection(message=''){if(message){renderer?.resync?.();revealResult();clearFightIntro();}disconnected=!!message;syncCommandState();const node=$('#connection');node.hidden=!message;node.innerHTML=message?`${esc(message)} ${button('Retry connection','refresh')}`:'';}
function spectatorToken(){const value=new URLSearchParams(location.hash.slice(1)).get('spectator');return /^[a-f0-9]{48}$/.test(value||'')?value:null;}
async function api(path,body){if(body!==undefined)requestGeneration++;const token=ticket(),serial=++requestSerial,sentAt=performance.now(),capability=body===undefined?spectatorToken():null,headers={...(body===undefined?{}:{'Content-Type':'application/json'}),...(capability?{'X-AXO-Spectator':capability}:{})};if(body!==undefined)pendingControls(true);try{const res=await fetch('/api/arena'+path,{credentials:'same-origin',cache:'no-store',...(body===undefined?{}:{method:'POST',body:JSON.stringify(body)}),...(Object.keys(headers).length?{headers}:{})});const data=await res.json();if(!current(token)||serial<(appliedReads.get(path)||0))throw stale();if(!res.ok){const e=new Error(data.error||'Arena connection failed.');e.status=res.status;throw e;}
 const match=path.match(/^\/(challenges|tournaments)\/([^/]+)(?:\/(move|join|ready|concede|start|leave))?$/);
 if(match){const id=decodeURIComponent(match[2]),old=match[1]==='challenges'?room:tournament;if(data.id!==id)throw stale();if(old?.id===id&&Number.isFinite(old.revision)&&data.revision<old.revision)throw stale();if(body===undefined){if(disconnected)renderer?.resync?.();connection();}}
 appliedReads.set(path,serial);if(data&&typeof data==='object')responseTiming.set(data,performance.now()-sentAt);return data;
 }catch(e){if(!current(token)||e.stale)throw stale();if(!e.status||e.status>=500){requestGeneration++;connection('Connection/save interrupted. No move is assumed saved. Reconnecting; the server clock continues.');}throw e;}finally{if(current(token)){pendingControls(false);syncCommandState();}}}

// Availability uses a separate short-lived lease channel. It never clears commitment errors.
function syncPresenceButton(){const node=$('[data-action="presence-toggle"]');if(node){node.disabled=presenceBusy;node.setAttribute('aria-pressed',String(presenceWanted));node.textContent=presenceWanted?'Hide my online status':'Appear online for challenges';}}
async function sendPresence(available){if(!config?.matchmaking)return false;const oldLease=presenceLease,epoch=++presenceEpoch,view=viewGeneration,hash=location.hash;if(!available)presenceLease=null;if(!available&&!oldLease){presenceBusy=false;return true;}presenceBusy=true;syncPresenceButton();presenceAttemptAt=Date.now();const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);
 try{const response=await fetch('/api/arena/presence',{method:'POST',credentials:'same-origin',cache:'no-store',keepalive:!available,headers:{'Content-Type':'application/json'},body:JSON.stringify({available,...(oldLease?{lease:oldLease}:{})}),signal:controller.signal});const result=await response.json();if(epoch!==presenceEpoch||view!==viewGeneration||hash!==location.hash)return false;if(!response.ok){if(response.status===409)presenceLease=null;throw Error(result.error||'Availability could not be refreshed.');}if(available&&presenceWanted&&tab==='challenge-room'&&!document.hidden)presenceLease=result.lease;return true;
 }catch(e){if(epoch===presenceEpoch&&view===viewGeneration&&available)toast('Online status unconfirmed. Entries disappear within45 seconds without a heartbeat.');return false;}finally{clearTimeout(timeout);if(epoch===presenceEpoch){presenceBusy=false;syncPresenceButton();}}}
function leavePresence(){if(presenceLease)void sendPresence(false);else{presenceEpoch++;presenceBusy=false;}presenceAttemptAt=0;}
function heartbeatPresence(){if(config?.matchmaking&&presenceWanted&&tab==='challenge-room'&&!document.hidden&&!presenceBusy&&Date.now()-presenceAttemptAt>=15000)void sendPresence(true);}
function renderMatchNotice(status){const node=$('#match-notice');if(!node)return;const active=status.activeMatch,invites=status.incoming||[];if(active?.needsConfirmation&&active.confirmationRequired&&active.petMatches){node.hidden=false;node.innerHTML=`<strong>${esc(active.opponent.name)} accepted /ready.</strong><span>Confirm to enter the battle.</span>${button('Accept & enter battle','confirm-match','primary',`data-id="${esc(active.id)}"`)}${button('Cancel invitation','invite-decline','quiet',`data-id="${esc(active.id)}"`)}`;}
 else if(invites.length&&!active){node.hidden=false;node.innerHTML=`<strong>Direct challenge${invites.length>1?'s':''}</strong>${invites.map(invite=>button(`${esc(invite.pet.name)} · View invitation`,'open-room','',`data-id="${esc(invite.id)}"`)).join('')}`;}
 else{node.hidden=true;node.innerHTML='';}}
function applyLobbyStatus(status){renderMatchNotice(status);const active=status.activeMatch;if(active?.status==='playing'&&active.petMatches&&!document.hidden&&!replay&&room?.id!==active.id){navigate('challenge',active.id);return true;}return false;}
async function loadLobbyStatus(){const status=await api('/lobby-status');return applyLobbyStatus(status);}
function onlinePlayers(b){if(!b.matchmakingEnabled)return '';const players=b.players||[];return `<section class="online-room card"><div class="row"><div><span class="eyebrow">LIVE READY ROOM</span><h2>Players online · ${players.length}</h2></div>${button(presenceWanted?'Hide my online status':'Appear online for challenges','presence-toggle',presenceWanted?'quiet':'primary',`aria-pressed="${presenceWanted}" ${presenceBusy?'disabled':''}`)}</div><p>Opt in to show your Pet name, lineage and level while this room is visible. No wallet address or private build is listed. Online means a heartbeat within45 seconds; up to${b.presenceLimit||50} other Pets shown.</p><div class="online-grid">${players.map(player=>`<article class="online-player"><div>${player.pet.art?`<img class="portrait" src="${esc(player.pet.art)}" alt="">`:''}<strong>${esc(player.pet.name)}</strong><small>Lv.${player.pet.level} · ${esc(player.pet.lineage)}</small><span class="online-status">${player.status==='available'?'● Available':'● In an entry'}</span></div>${button('Challenge Pet','direct-challenge','primary',`data-id="${esc(player.id)}" aria-label="Challenge ${esc(player.pet.name)}" ${player.canChallenge?'':'disabled'}`)}</article>`).join('')||'<p class="muted">No other visible Pets yet. Appear online to receive a direct invitation.</p>'}</div></section>`;}
function clearFightIntro(){fightIntro=null;const node=$('#fight-intro');if(node)node.hidden=true;}
function armFightIntro(r){if(document.hidden||r.status!=='playing'||!r.countdownMs||(responseTiming.get(r)||0)>1000){clearFightIntro();return;}if(fightIntro?.id!==r.id&&r.phase==='countdown'&&r.serverNow<r.startedAt)fightIntro={id:r.id,startsAt:r.startedAt};updateFightIntro();}
function updateFightIntro(){const node=$('#fight-intro');if(!node||!fightIntro||room?.id!==fightIntro.id||document.hidden||disconnected){if(node)node.hidden=true;return;}const now=Date.now()+clockOffset,left=Math.ceil((fightIntro.startsAt-now)/1000);let text='';if(room.phase==='countdown')text=left>0?String(Math.min(3,left)):'SYNC…';else if(now>=fightIntro.startsAt&&now<fightIntro.startsAt+1000)text='FIGHT';if(!text){node.hidden=true;fightIntro=null;return;}node.hidden=false;node.dataset.phase=text==='FIGHT'?'fight':'countdown';const label=$('#fight-count');if(label&&label.textContent!==text)label.textContent=text;}

function toast(text){if(text==='Superseded view')return;$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
function setContent(html){labController?.destroy();labController=null;clearResult();clearFightIntro();clearInterval(replayTimer);replayTimer=null;renderer?.stop();renderer=null;document.body.classList.toggle('in-battle',html.includes('id="battle-canvas"'));document.body.classList.toggle('in-workshop',html.includes('id="pet-workshop"'));main.innerHTML=html;main.scrollTop=0;}
function button(label,action,cls='',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
function portrait(p){const layers=p.layers?.length?p.layers:[{url:p.art}];return `<div class="scene-portrait" aria-label="${esc(p.name)} canonical Hatchery appearance">${layers.map((v,i)=>`<img src="${esc(v.url)}" alt="${i?'':esc(p.name)}" loading="lazy">`).join('')}</div>`;}
function summary(p){return `<div class="pet-summary">${portrait(p)}<div><strong>${esc(p.name)}</strong><br><small>${esc(LINEAGES[p.lineageId].name)} · Lv. ${p.level}</small><br><small>${p.xp} Hatchery XP · ${esc(p.genesisId)}</small></div></div>`;}
function publicSummary(p){return `<div class="pet-summary privacy-summary">${portrait(p)}<div><strong>${esc(p.name)}</strong><br><small>${esc(LINEAGES[p.lineageId]?.name||p.lineage||'AXO Pet')} · Lv. ${Number(p.level)||'?'}</small><br><small>Private fighter details hidden</small></div></div>`;}
function spectatorUrl(type,id,token){const url=new URL(location.href);url.search='';url.hash=type+'='+encodeURIComponent(id)+'&spectator='+encodeURIComponent(token);return url.href;}
function moderationButtons(r){if(!r?.moderation?.available)return '';return button(r.moderation.blocked?'Unblock player':'Block player','block-player','quiet',`data-blocked="${!r.moderation.blocked}"`)+button('Report player','report-player','quiet');}
function spectatorPanel(access,{kind='room',id}={}){if(!access)return '';const prefix=kind==='tournament'?'tournament-':'';const capabilities=access.capabilities||[],share=spectatorShare?.kind===kind&&spectatorShare.id===id?spectatorShare:null;return `<aside class="spectator-access card" aria-label="Private spectator access"><div><span class="eyebrow">PRIVATE SPECTATOR ACCESS</span><h3>${access.allConsented?'Consent complete':'Waiting for mutual consent'}</h3><p>Full builds and battle detail require every participant’s consent and a revocable capability link.</p></div><div class="actions">${button(access.allowed?'Spectators consented':'Allow spectators',prefix+'spectator-consent','quiet',`data-allowed="${!access.allowed}"`)}${access.canIssue&&access.allConsented?button('Create spectator link',prefix+'spectator-create','primary'):''}</div>${share?`<div class="spectator-share"><label>Copy this link now<input readonly value="${esc(share.url)}" aria-label="New private spectator link"></label>${button('Copy link','copy-spectator-link','primary')}</div>`:''}${capabilities.length?`<div class="capability-list"><small>ACTIVE LINKS</small>${capabilities.map(cap=>`<div><code>${esc(cap.id.slice(0,10))}…</code><span>${new Date(cap.createdAt).toLocaleString()}</span>${button('Revoke',prefix+'spectator-revoke','quiet',`data-id="${esc(cap.id)}"`)}</div>`).join('')}</div>`:'<small>No active spectator links.</small>'}</aside>`;}
function openReportPanel(){openGamePanel('Private player report',`<p>Choose the closest category. A Private report receipt stays inside Arena and includes no public message or wallet address.</p><div class="report-options">${[['harassment','Harassment'],['identity_leak','Identity or privacy leak'],['invite_abuse','Invitation abuse'],['other','Other']].map(([key,label])=>button(label,'report-category','quiet',`data-category="${key}"`)).join('')}</div>`);}
function setTab(v){tab=v;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===v));}
async function boot(){const token=ticket();try{config=await api('/config');}catch(e){if(e.stale||token.view!==viewGeneration)return;config={mode:'authenticated'};}
 $('#mode').textContent=config.syntheticOnly?'SYNTHETIC PIPELINE REVIEW · INVENTED PET / GEAR · NO LIVE WALLET':config.mode==='preview'?'PRIVATE PLAYABLE REVIEW · TEST PETS · NO HATCHERY XP CHANGES · NO AXO WAGERS':(config.beta?'PUBLIC BETA · HATCHERY-BOUND PETS · FREE PLAY · NO WAGERS':'AXO PET ARENA · HATCHERY-BOUND PETS · FREE PLAY');
 if(new URLSearchParams(location.hash.slice(1)).has('style-lab')){await route();return;}
 try{me=await api('/me');connection();await route();}catch(e){if(e.stale)return;if(e.status===401){me=null;login();}else if(e.status===503)verificationUnavailable();else toast(e.message);}}
function verificationUnavailable(){me=null;draft=null;connection();navigating=false;setContent('<section class="entry-screen"><span class="eyebrow">PET VERIFICATION PAUSED</span><h1>Reconnect your Pet.</h1><p>Identity or equipped gear could not be verified. No new battle can start until the read succeeds. Existing fights keep their frozen entry build.</p><div class="actions"><a href="/hatchery">Open Hatchery ↗</a>'+button('Retry verified read','refresh','primary')+'</div></section>');}
function login(){navigating=false;setContent(`<section class="login entry-screen"><div class="entry-emblem" aria-hidden="true">AXO</div><div class="eyebrow">PET ARENA / FREE-PLAY BETA</div><h1>Enter the arena.</h1><p class="muted">Raise your AXO in the Hatchery. Bring its lineage, growth and battle build into the Arena.</p>${config.mode==='preview'?`<div class="card"><h2>Choose a review Pet</h2><p>These are test profiles using canonical AXO lineage designs, not your live Hatchery Pet. Open a second browser profile to try two-player challenges.</p><form id="preview-form"><label>Pet name<input name="name" value="Anon’s AXO" maxlength="32" required></label><label>Lineage<select name="lineageId">${Object.entries(LINEAGES).map(([id,l])=>`<option value="${id}">${l.name}</option>`).join('')}</select></label><label>Test level<select name="level">${XP.map((_,i)=>`<option value="${i+1}" ${i===9?'selected':''}>Level ${i+1}</option>`).join('')}</select></label><button class="primary">Enter Arena</button></form></div>`:`<div class="card"><h2>Bring your Hatchery Pet</h2><p>Connect your wallet in Hatchery, then return here. Arena reads the authenticated Pet; you cannot import a different wallet’s fighter.</p><a href="https://axo.pet/hatchery">Open Hatchery · AXO.pet ↗</a> ${button('Check connection','refresh')}</div>`}</section>`);}
async function route(){beginView();const token=ticket();const params=new URLSearchParams(location.hash.slice(1)),id=params.get('challenge'),tid=params.get('tournament');firstRunPrompt=params.has('guided-practice');replay=null;routeKey=location.hash;lastRevision=-1;lastLog=0;
 if(params.has('style-lab')){setTab('style-lab');renderStyleLab(params);}
 else if(params.has('challenge-room')){setTab('challenge-room');room=null;tournament=null;await loadChallengeRoom(true);}
 else if(id){setTab('arena');room=await api('/challenges/'+encodeURIComponent(id));tournament=null;renderRoom(true);}
 else if(tid){setTab('tournaments');tournament=await api('/tournaments/'+encodeURIComponent(tid));room=null;renderTournament();}
 else{room=null;tournament=null;renderTab();}if(current(token)){navigating=false;syncCommandState();}
 if(current(token)&&params.get('view')==='report'&&room&&room.seat>=0&&['won','draw'].includes(room.status)){if(await loadReplay())showBattleReport();}}
function renderTab(){if(!me)return login();if(tab==='challenge-room'){loadChallengeRoom(true).catch(e=>toast(e.message));return;}if(tab==='build')return renderBuild();if(tab==='tournaments')return tournamentHome();home();}
function home(){setContent(commandCenterMarkup(me,{synthetic:config.mode==='preview'||config.syntheticOnly===true,guided:firstRunPrompt}));renderer=new ArenaRenderer($('#hero'));renderer.hero=me.pet;}
function renderStyleLab(params=new URLSearchParams()){setContent(styleLabMarkup());labController=mountStyleLab(main.querySelector('.style-lab'),{initialLineage:me?.pet.lineageId,params});$('#style-lab-title').focus({preventScroll:true});}
function presentationSettings(){const p=activePresentation();openGamePanel('Presentation settings',`<div class="arena-presentation-settings"><label>Graphics<select data-arena-setting="quality">${['auto','low','high'].map(value=>`<option value="${value}" ${p.quality===value?'selected':''}>${value==='auto'?'Auto · device aware':value==='low'?'Low · 30 FPS / lower resolution':'High · 60 FPS'}</option>`).join('')}</select></label><label>Motion<select data-arena-setting="motion"><option value="system" ${p.motion==='system'?'selected':''}>Follow system preference</option><option value="reduced" ${p.motion==='reduced'?'selected':''}>Reduced motion</option></select></label><label>Combat readouts<input type="checkbox" data-arena-setting="readouts" ${p.readouts?'checked':''}></label><label>Higher text contrast<input type="checkbox" data-arena-setting="contrast" ${p.contrast?'checked':''}></label><p>Settings apply to presentation only and stay in this browser. Operating-system reduced motion is always respected. Hidden tabs stop painting. Sound is controlled separately.</p></div>`);}
document.body.classList.toggle('arena-contrast',activePresentation().contrast);
document.addEventListener('change',event=>{const key=event.target.dataset?.arenaSetting;if(!key)return;const p=updatePresentation({...activePresentation(),[key]:event.target.type==='checkbox'?event.target.checked:event.target.value});document.body.classList.toggle('arena-contrast',p.contrast);});
function arcadeDecals(){return `<div class="arcade-decals" aria-hidden="true"><span class="decal decal-hodl">HODL // HIT // REPEAT</span><span class="decal decal-rug">RUG PULL ZONE</span><span class="decal decal-free">FREE PLAY<br><b>NO WAGERS</b></span></div>`;}
function uiIcon(kind){const paths={sword:'M5 3l14 14M3 5l4-2 14 14-4 4L3 7zm11 13 4-4M3 21l4-4',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',surge:'M13 2L4 14h7l-1 8 10-13h-7z',heal:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6z',epic:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3zM3 3l2 2m14 14 2 2',target:'M12 2v4m0 12v4M2 12h4m12 0h4M5 5l3 3m8 8 3 3M5 19l3-3m8-8 3-3',crown:'M3 6l4 4 5-7 5 7 4-4-2 13H5zM6 22h12',book:'M4 3h14l2 2v16H4zM8 7h7M8 11h7M8 15h5',arrow:'M4 18L19 3M9 3h10v10',down:'M4 4l15 15M9 19h10V9',reset:'M4 8a9 9 0 1 1-1 7M4 2v6h6',gear:'M12 3v4m0 10v4M3 12h4m10 0h4M6 6l3 3m6 6 3 3M6 18l3-3m6-6 3-3M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8'};return `<svg class="game-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[kind]||paths.sword}"/></svg>`;}
function moveSymbol(key,m){return uiIcon(key==='epic'?'epic':key==='recharge'?'surge':key==='rug_pull'?'down':key==='pepe_breakout'?'arrow':key==='reversal'?'reset':m?.heal?'heal':m?.branch==='defense'?'shield':'sword');}
function fieldGuide(){openGamePanel('Arena field guide',`<p class="guide-warning">Live battles do not pause while a menu is open.</p><div class="guide-grid"><article>${uiIcon('sword')}<h3>Commit · one tap locks</h3><p>You have 10 seconds per exchange. Choose one move with keys <kbd>1</kbd>–<kbd>4</kbd> or tap its icon. Your choice stays hidden until both players lock; it cannot be changed. Both attacks land. Inspect moves explains costs without committing.</p></article><article>${uiIcon('surge')}<h3>Manage energy</h3><p>Start with 6/10 energy. Strong attacks and defenses cost 3–4; basic attack and guard are free. Recover 2 after every resolved exchange. <kbd>R</kbd> restores up to 4 total but gives no attack or shield. Cooldowns count exchanges, not seconds.</p></article><article>${uiIcon('epic')}<h3>Unleash</h3><p><kbd>E</kbd> uses your learned epic when charge and lineage conditions allow. Once per battle.</p></article><article>${uiIcon('gear')}<h3>Build your Pet</h3><p>Assign stats, upgrade ranks and equip four moves in Pet build. Save explicitly between entries.</p></article></div><section class="first-battle-rules"><h3>Survive the clock</h3><p>A missed turn uses Gas Station. Three consecutive missed turns forfeit; if both players miss three, the battle draws. Menus, refreshes and disconnects never pause the server clock.</p><p>From exchange 10, Liquidation hits both Pets for 6 damage, then 4 more each exchange; healing is halved. At 14 exchanges or 180 seconds, higher remaining HP percentage wins; equal percentages draw.</p><p>Double KO? Photo Finish compares proportional overkill: the smaller overkill survives at 1 HP; an exact tie draws. Free play: no wagers, purchases for power or battle XP.</p></section><p class="muted">30–60 fps presentation targets (Low/High) · Continuous phase arcs, receiver recoil and a terminal stance blend; 217 offline motion samples per 1.8-second sequence at 120 Hz (not measured device FPS). Eight original fallback poses per lineage; four unchanged Emerald clips / 16 authored poses, plus signature and epic clips for five additional lineages / 40 new authored poses. Other regular and recovery moves remain procedural. Interpolation adds rendered transitions, not newly painted anatomy. Degen stamps and sparks follow resolved receipts only. Actual performance depends on device. Reduced motion follows your system setting. Free play; no wagers or battle XP.</p>`);}

function openGamePanel(title,body){poseInspector?.destroy();poseInspector=null;document.querySelector('#game-panel')?.remove();const opener=document.activeElement,dialog=document.createElement('dialog');dialog.id='game-panel';dialog.className='game-panel';dialog.setAttribute('aria-label',title);dialog.innerHTML=`<div class="row"><h2>${esc(title)}</h2>${button('×','close-panel','icon-button','aria-label="Close panel"')}</div>${body}`;document.body.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();dialog.close();});dialog.addEventListener('close',()=>{const ownedInspector=dialog._poseInspector;ownedInspector?.destroy();if(poseInspector===ownedInspector)poseInspector=null;dialog.remove();if(dialog.dataset.panel==='move-inspection')document.querySelector('[data-action="inspect-moves"]')?.focus({preventScroll:true});else if(opener?.isConnected)opener.focus({preventScroll:true});});dialog.showModal();}
function historyPanel(){openGamePanel('Match history',`<div class="history game-history">${me.rooms.length?me.rooms.slice().reverse().map(r=>button(`<strong>${esc(r.opponent)}</strong><span>${esc(r.result)} · ${r.practice?'Practice':r.tournament?'Tournament':'Casual'}</span><small>${esc(r.reason.replaceAll('_',' '))} · ${new Date(r.finishedAt||r.createdAt).toLocaleString()} · ${['won','draw'].includes(r.status)?'Battle report':'Open entry'}</small>`,['won','draw'].includes(r.status)?'open-battle-report':'open-room','history-row',`data-id="${r.id}"`)).join(''):'<p>No battles yet. Your completed bouts and replays will appear here.</p>'}</div>`);}

async function loadChallengeRoom(focus=false,force=false){const next=await api('/challenge-room');if(tab!=='challenge-room'||room||tournament)return;if(next.matchmakingEnabled&&applyLobbyStatus(next))return;heartbeatPresence();const changed=JSON.stringify({...next,serverNow:0})!==JSON.stringify({...board,serverNow:0});board=next;clockOffset=next.serverNow-Date.now();if(changed||force||focus||!$('#challenge-room-title'))renderChallengeRoom(focus);}
function renderChallengeRoom(focus=false){const b=board,active=document.activeElement,restore=active?.dataset.action,restoreId=active?.dataset.id;
 setContent(`<section class="challenge-room"><div class="section-head"><div><div class="eyebrow">THE DOJO NOTICEBOARD · IN-APP ONLY</div><h1 id="challenge-room-title" tabindex="-1">Challenge Room</h1><p>Post your Pet. Find a rival. Let the moves do the talking.</p></div>${button('Back to lobby','lobby','quiet')}</div><p class="notice"><strong>Free play · no AXO at stake.</strong> No fees, rewards or wagers. Posting adds an in-Arena card only—not a social post or chat. Acceptance asks the host to confirm. Both enter a3-second countdown before fighting. Pets must be within one level.</p>${onlinePlayers(b)}<section class="card own-challenge"><h2>Your challenge</h2>${b.own?`<p>${b.own.posted?'Your card is on the board.':'Your waiting challenge is not posted.'} Removing a card keeps the challenge and its original expiry.</p><div class="actions">${button('Open my challenge','open-room','',`data-id="${b.own.id}"`)}${b.own.petMatches?button(b.own.posted?'Remove from Challenge Room':'Post to Challenge Room','board-post','primary',`data-id="${b.own.id}" data-posted="${!b.own.posted}"`):'<span role="status">Your entered Pet has changed. Open and cancel the old entry before creating another.</span>'}</div>`:b.busy?'<p role="status">Your Pet already has an active battle, invitation or roster. Finish or cancel that entry before posting a new challenge.</p>':`<p>No waiting challenge yet. Create one first; posting is a separate, explicit choice.</p>${button('Create casual challenge','board-create','primary')}`}</section><div class="section-head"><h2 aria-live="polite">Open challenges <small>· ${b.cards.length} / ${b.limit} shown</small></h2>${button('Refresh challenges','board-refresh','quiet')}</div><p class="muted">Newest posts first · five-minute challenge expiry · builds and private choices stay off this board.</p><div class="challenge-grid">${b.cards.length?b.cards.map(c=>{const own=c.id===b.own?.id,eligible=Math.abs(c.pet.level-me.pet.level)<=1;return `<article class="card challenge-card"><div class="row">${c.pet.art?`<img class="portrait" src="${esc(c.pet.art)}" alt="${esc(c.pet.name)} · canonical level ${c.pet.level} portrait" loading="lazy">`:'<span class="challenge-icon" aria-hidden="true">◆</span>'}<span class="chip">FREE PLAY · NO AXO</span></div><h3>${esc(c.pet.name)}</h3><p>${esc(c.pet.lineage)}<br><strong>Level ${c.pet.level}</strong></p><p class="muted"><small>Posted <time datetime="${new Date(c.postedAt).toISOString()}">${new Date(c.postedAt).toLocaleTimeString()}</time><br>Expires <time datetime="${new Date(c.expiresAt).toISOString()}">${new Date(c.expiresAt).toLocaleTimeString()}</time> · <span data-board-expiry="${c.expiresAt}"></span></small></p>${own?button('Open my challenge','open-room','',`data-id="${c.id}"`):button('Accept challenge','board-accept','primary',`data-id="${c.id}" aria-label="Accept challenge from ${esc(c.pet.name)}" ${b.busy||!eligible?'disabled':''}`)}${!own&&(b.busy||!eligible)?`<p><small>${b.busy?'Finish your active entry first.':'Requires a Pet within one level.'}</small></p>`:''}</article>`;}).join(''):'<div class="card challenge-empty"><h3>No open calls. Yet.</h3><p>The board is quiet. Create a casual challenge and explicitly post it here. Accepted, removed and expired cards disappear automatically.</p></div>'}</div><p class="muted">Optional manual invite links stay in your waiting room. No messages, uploads, handles or external links can be added to a card. This temporary board is not match history.</p></section>`);
 if(focus)$('#challenge-room-title').focus({preventScroll:true});else if(restore){const candidates=[...main.querySelectorAll('[data-action]')];(candidates.find(n=>n.dataset.action===restore&&n.dataset.id===restoreId)||$('#challenge-room-title')).focus({preventScroll:true});}
}
