function energyForecast(f,key){const m=f.build.skills[key];if(!m)return '';const cost=m.cost,after=f.energy-cost;if(after<0)return `${m.name}: needs ${cost} EN · short ${-after} · choose a free move or recharge.`;return `${m.name}: ${cost?cost+' EN cost':'FREE'} · ${f.energy} → ${after} after spend → ${Math.min(10,after+2+(m.energy||0))} after recovery${f.build.lineageId==='emerald_sprout'?' · block passive may add 1':''}.`;}
function energyMeter(f,label){return `<div class="hud-energy" role="meter" aria-label="${esc(label)} energy" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${f.energy}"><div class="hud-energy-fill" style="width:${f.energy*10}%"></div><span>ENERGY <b>${f.energy} / 10</b></span></div>`;}
function moveText(v){return [v.damage?`${v.damage} DMG`:null,v.shield?`${v.shield} shield`:null,v.heal?`${v.heal} heal`:null,v.counter?`counter ≤${v.counter}`:null,v.purge?`strip ${v.purge} shield`:null,v.pierce?`${Math.round(v.pierce*100)}% bypass`:null,v.energy?`+${v.energy} energy`:null,v.recoil?`${v.recoil} recoil`:null,v.cleanse?'cleanse':null,v.weak?`${Math.round(v.weak*100)}% weaken`:null,v.buff?`+${v.buff} next attack`:null].filter(Boolean).join(' · ');}
